"""Irreversible savings-account close gated by ``requires_confirmation``."""

from __future__ import annotations

from rasa.mantle.tools.decorator import ToolContext, tool
from rasa.mantle.tools.result import ToolResult

# Eval-only sentinel: close tool returns an error for this account name.
_FAILING_ACCOUNT_NAME = "unavailable account"


@tool(
    description=(
        "Permanently close the named savings account after the customer "
        "confirms. Call once account_name and close_reason are recorded; the "
        "engine asks for confirmation before this tool runs."
    ),
)
async def close_savings_account(context: ToolContext) -> ToolResult:
    account_name = str(context.memory.get("account_name") or "").strip()
    close_reason = str(context.memory.get("close_reason") or "").strip()
    if not account_name or not close_reason:
        return ToolResult(
            llm_response={
                "ok": False,
                "error": "account_details_incomplete",
                "hint": (
                    "Record account_name and close_reason via set_fields "
                    "before closing."
                ),
            }
        )

    if account_name.casefold() == _FAILING_ACCOUNT_NAME:
        return ToolResult(
            llm_response={
                "ok": False,
                "error": "account_close_failed",
            }
        )

    context.memory.set("account_closed", True)
    return ToolResult(
        llm_response={
            "ok": True,
            "account_closed": True,
            "account_name": account_name,
            "close_reason": close_reason,
        }
    )
